void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;

    float intensity = 0.025;
    vec2 center = vec2(0.5, 0.5);
    float dist = length(center - uv);

    vec2 red_offset = uv + dist * intensity;
    vec2 green_offset = uv;
    vec2 blue_offset = uv - dist * intensity;
    vec3 color;
    color.r = texture(iChannel0, red_offset).r;
    color.g = texture(iChannel0, green_offset).g;
    color.b = texture(iChannel0, blue_offset).b;

    fragColor = vec4(color, 1.0f);
}
